import{_ as n,o as s,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS Infernalis (Day 1) -- RBD: Async Mirroring","description":"","frontmatter":{"title":"CDS Infernalis (Day 1) -- RBD: Async Mirroring","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-06T00:00:00.000Z","tags":["Ceph","RBD","Async Mirroring","Data Replication","Disaster Recovery"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_1_--_RBD_-_Async_Mirroring.md","filePath":"posts/2015/CDS_Infernalis_Day_1_--_RBD_-_Async_Mirroring.md","lastUpdated":1780459816000}'),i={name:"posts/2015/CDS_Infernalis_Day_1_--_RBD_-_Async_Mirroring.md"};function l(a,r,e,g,_,p){return s(),t("div",null,[...r[0]||(r[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph RBD 异步镜像机制的设计与讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Josh（主持人）、Jason、Lars、LS 等</p><p><strong>会议内容</strong>：</p><p><strong>1. 会议背景与目标</strong></p><p>当前Ceph的RBD镜像支持在集群内同步复制，但缺乏灾难恢复能力。本次会议旨在讨论并设计一种异步镜像机制，实现RBD镜像在不同数据中心或地理位置的复制，保证数据一致性和灾难恢复能力。</p><p><strong>2. 设计方案</strong></p><ul><li><strong>异步镜像机制</strong>： 基于RBD镜像的完整日志，实现数据异步复制。</li><li><strong>日志存储</strong>： 使用对象存储池存储日志，可配置为与RBD存储池相同或不同。</li><li><strong>日志模式</strong>： 支持写入回模式（writeback）和写入透传模式（writethrough）。</li><li><strong>日志管理</strong>： 通过Journal header记录日志信息，包括填充策略、前缀、flush位置、不同站点/区域的复制位置等。</li><li><strong>复制粒度</strong>： 可在单个RBD镜像或整个存储池级别进行配置。</li></ul><p><strong>3. 关键技术</strong></p><ul><li><strong>日志记录</strong>： 使用独占锁确保日志写入的原子性。</li><li><strong>数据一致性</strong>： 通过完整数据日志保证复制数据的完整性。</li><li><strong>性能优化</strong>： 通过缓存机制减少写操作对性能的影响。</li></ul><p><strong>4. 讨论与决策</strong></p><ul><li><strong>日志存储位置</strong>： 可配置为与RBD存储池相同或不同，以提高性能。</li><li><strong>复制粒度</strong>： 可在单个RBD镜像或整个存储池级别进行配置。</li><li><strong>一致性组</strong>： 可支持多个RBD镜像共享同一个日志，提高效率。</li><li><strong>后续工作</strong>： <ul><li>设计并实现日志模块。</li><li>实现异步复制功能。</li><li>优化性能。</li></ul></li></ul><p><strong>5. 行动计划</strong></p><ul><li>Josh：负责设计日志模块。</li><li>Jason：负责实现异步复制功能。</li><li>Lars：负责性能优化。</li><li>LS：负责测试。</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了Ceph异步镜像机制的设计方案，明确了关键技术、讨论了相关技术问题，并制定了后续行动计划。该方案将为Ceph提供强大的灾难恢复能力，提高数据安全性。</p>',17)])])}const u=n(i,[["render",l]]);export{c as __pageData,u as default};
